class Solution {
    public long numberOfWeeks(int[] milestones){
        long sum=0,maximum=0;
        for(int value:milestones){
            sum+=value;
            maximum=Math.max(maximum,value);
        }
        long rest=sum-maximum;
        return maximum<=rest+1?sum:2*rest+1;
    }
}

code.kotlin:
class Solution {
    fun numberOfWeeks(milestones:IntArray):Long{
        val sum=milestones.sumOf{
            it.toLong()
        };
        val maximum=milestones.maxOrNull()!!.toLong();
        val rest=sum-maximum;
        return if(maximum<=rest+1)sum else 2*rest+1
    }
}

